140	// CALIBRATION HOOK (test_mamba_tc.py::test_tc_proj_dw_exact_on_own_operands):
141	// slice the kernel's OWN stored bf16 acts dY_dyout[L1] [T,d] and X_ygated[L1]
142	// [T,d_inner] from the workspace, returned as fp32 CPU tensors. The gate
143	// contracts them in fp32 ascending-t and compares to the kernel's
144	// out_proj.weight grad slice — isolating the output-stationary dW GEMM (K=T)
145	// from the operand-chain bf16 divergence. A ~1e-6 match proves the dW GEMM is
146	// bit-exact on its own operands, calibrating the per-tensor bf16 tol as headroom
147	// over a GEMM-exact floor. Reuses the cached workspace (call AFTER tc_train_step).
148	static std::vector<torch::Tensor> tc_dump_outproj_operands(torch::Tensor params, int64_t B) {
149	    // OBSOLETE on the Mamba-3 scalar-per-sample path: there is no stored bf16 acts
150	    // region (the dW is accumulated scalar-style into the per-CTA full-grad partial,
151	    // not output-stationary on wgmma). The Mamba-1 calibration hook this served is
152	    // not part of the fp64 parity gate; the grad parity is validated end-to-end by
153	    // the keystone grad-parity test + the looksam/SG sam_dir/sharpness gates.
154	    (void)params; (void)B;
155	    TORCH_CHECK(false, "tc_dump_outproj_operands: obsolete on the Mamba-3 scalar path "
156	                       "(no stored bf16 projection acts; dW is in the full-grad partial).");
157	    return {};
158	}
