161	// scalar_train_step: the SAME (mamba × AdamW) cell run through the SCALAR default
162	// launcher (launch_fused_mamba_megakernel<AdamW>, OUTSIDE the wgmma guard — this
163	// wgmma-token TU can still call it). For the step-time gate to time scalar and TC
164	// back-to-back in one process / one contention regime → an honest scalar:TC ratio.
165	// The scalar path uses its OWN workspace (nCTA*total partials + nCTA loss + 1).
166	// NOT the shipped invocation (that is dispatch.cpp via mega_mamba_real_adamw.cu);
167	// a measurement mirror. Returns {loss, reduced grad}. NOTE: the scalar mamba
168	// kernel needs ~142KB DYNAMIC smem (its launcher does the opt-in internally). GATED
169	// by SG_MB_SCALAR_MEGAKERNEL: at the d-scaled bench width the scalar megakernel's
170	// MambaSampleSmem overflows the smem budget and is compiled out (the TC path is what
171	// the bench measures), exactly as the decoder bench gates its scalar step.
172	static std::vector<torch::Tensor> scalar_train_step(
173	        torch::Tensor params, torch::Tensor tokens, torch::Tensor targets,
174	        torch::Tensor state, double lr, double beta1, double beta2, double eps,
175	        double weight_decay, double bc1, double bc2, int64_t step) {
176	    TORCH_CHECK(params.is_cuda() && params.scalar_type() == torch::kFloat32 && params.is_contiguous());
177	    TORCH_CHECK(params.numel() == kMambaTotalElems, "params must be the flat mamba blob (", kMambaTotalElems, ")");
178	    TORCH_CHECK(tokens.is_cuda() && tokens.scalar_type() == torch::kInt32 && tokens.is_contiguous());
179	    TORCH_CHECK(targets.is_cuda() && targets.scalar_type() == torch::kInt32 && targets.is_contiguous());
180	    const int B = (int)targets.numel();
181	    TORCH_CHECK(tokens.numel() == (int64_t)B * mb::kSeq, "tokens must be [B,kSeq]");
182	    const int64_t total = kMambaTotalElems;
183	    TORCH_CHECK(state.is_cuda() && state.scalar_type() == torch::kFloat32 && state.is_contiguous()
184	                && state.numel() >= 3 * total, "state must be contiguous fp32 [>=3*total]");
185	
186	    int dev = params.get_device();
187	    int n_sms = 1;
188	    cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
189	
190	    static torch::Tensor s_gn, s_ga, s_gg, s_ws;
191	    static int64_t s_ws_floats = 0;
192	    const int64_t need = (int64_t)n_sms * total + n_sms + 1;
193	    if (!s_gn.defined()) {
194	        auto oi = torch::dtype(torch::kInt32).device(params.device());
195	        s_gn = torch::zeros({1}, oi); s_ga = torch::zeros({1}, oi); s_gg = torch::zeros({1}, oi);
196	    }
197	    if (s_ws_floats < need) {
198	        s_ws = torch::empty({need}, torch::dtype(torch::kFloat32).device(params.device()));
199	        s_ws_floats = need;
200	    }
201	    auto grad = torch::zeros({total}, torch::dtype(torch::kFloat32).device(params.device()));
202	    float* loss_out = s_ws.data_ptr<float>() + (int64_t)n_sms * total + n_sms;
203	
204	    PersistentContext ctx{
205	        s_gn.data_ptr<int>(),
206	        reinterpret_cast<unsigned*>(s_ga.data_ptr<int>()),
207	        reinterpret_cast<unsigned*>(s_gg.data_ptr<int>()),
208	        ::sg::fused::sm90::kMambaNumTensors, 0u};
209	
210	    FusedOptState st;
211	    float* m = state.data_ptr<float>();
212	    st.exp_avg = m; st.exp_avg_sq = m + total;
213	    st.lr = (float)lr; st.beta1 = (float)beta1; st.beta2 = (float)beta2;
214	    st.eps = (float)eps; st.wd = (float)weight_decay;
215	    st.bc1 = (float)bc1; st.bc2 = (float)bc2;
216	
217	    MambaTokenCtx tok;
218	    tok.tokens = tokens.data_ptr<int>();
219	    tok.targets = targets.data_ptr<int>();
220	    tok.B = B;
221	    tok.workspace = s_ws.data_ptr<float>();
222	    tok.loss_out = loss_out;
223	
224	    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
225	    cudaError_t err = ::sg::fused::sm90::launch_fused_mamba_megakernel<OptId::AdamW>(
226	        ctx, params.data_ptr<float>(), tok, grad.data_ptr<float>(),
227	        (float)lr, (int)step, st, stream);
228	    TORCH_CHECK(err == cudaSuccess, "scalar mamba megakernel launch failed: ", cudaGetErrorString(err));
229	    C10_CUDA_CHECK(cudaStreamSynchronize(stream));
230	
231	    auto loss_cpu = s_ws.slice(0, (int64_t)n_sms * total + n_sms, (int64_t)n_sms * total + n_sms + 1)
232	                        .to(torch::kCPU);
233	    return {loss_cpu, grad};
234	}
235	#endif  // SG_MB_SCALAR_MEGAKERNEL
